// src/mcp/tools/notes-read.ts
function notesReadTool(server) {
  server.registerTool("notes_read", {
    description: "Read a reference note. Use reference name for the index note, or reference/subpath for a sub-note.",
    inputSchema: {
      path: stringType().describe("Reference name or reference/subpath")
    }
  }, (input) => runTool(gen2(function* () {
    const refs = yield* ReferencesService;
    const content = yield* refs.readNote(input.path);
    return ok(content);
  }).pipe(catchTag2("ReferenceNotFound", (err) => succeed6(fail10(`Reference not found: ${err.name}`))), catchTag2("NoteNotFound", (err) => succeed6(fail10(`Note not found for ${err.name}: ${err.path}. Available note paths: ${err.available.join(", ")}`))))));
}

// src/mcp/tools/notes-write.ts
function notesWriteTool(server) {
  server.registerTool("notes_write", {
    description: "Create or overwrite a reference note. The reference must already exist.",
    inputSchema: {
      path: stringType().describe("Reference name or reference/subpath"),
      content: stringType()
    }
  }, (input) => runTool(gen2(function* () {
    const refs = yield* ReferencesService;
    const entry = yield* refs.writeNote(input.path, input.content);
    return ok(entry);
  }).pipe(catchTag2("ReferenceNotFound", (err) => succeed6(fail10(`Reference not found: ${err.name} \u2014 create it with reference_upsert first`))))));
}

// src/mcp/tools/reference-delete.ts
function referenceDeleteTool(server) {
  server.registerTool("reference_delete", {
    description: "Delete a reference entry. Errors if the entry does not exist.",
    inputSchema: {
      name: stringType()
    }
  }, (input) => runTool(gen2(function* () {
    const refs = yield* ReferencesService;
    yield* refs.delete(input.name);
    return ok({ deleted: input.name });
  }).pipe(catchTag2("ReferenceNotFound", (err) => succeed6(fail10(`Reference not found: ${err.name}`))))));
}

// src/mcp/tools/reference-get.ts
function referenceGetTool(server) {
  return server.registerTool("reference_get", {
    description: "Get the full entry for a named reference.",
    inputSchema: {
      name: stringType().describe("Reference name to look up")
    }
  }, (input) => runTool(gen2(function* () {
    const refs = yield* ReferencesService;
    const entry = yield* refs.get(input.name);
    const indexNote = entry.notes.find((note) => note.path === "");
    const files = entry.notes.filter((note) => note.path !== "").map((note) => note.path);
    return ok({
      domains: entry.domains,
      repo: entry.repo,
      note: indexNote?.content,
      files
    });
  }).pipe(catchTag2("ReferenceNotFound", (err) => succeed6(fail10(`Reference not found: ${err.name}`))))));
}

// src/mcp/tools/reference-search.ts
function referencesSearchTool(server) {
  server.registerTool("references_search", {
    description: "Case-insensitive substring search across reference names, domains, repo, and notes. Returns a terse list; call reference_get for full detail.",
    inputSchema: {
      keyword: stringType().describe("Substring to search for")
    }
  }, (input) => runTool(gen2(function* () {
    const refs = yield* ReferencesService;
    const results = yield* refs.search(input.keyword);
    return ok(results);
  })));
}

// src/mcp/tools/reference-upsert.ts
function referenceUpsertTool(server) {
  server.registerTool("reference_upsert", {
    description: "Create or update a reference entry's domains and repo, then persist. Notes are managed by notes_write and notes_edit.",
    inputSchema: {
      name: stringType(),
      domains: arrayType(stringType()),
      repo: stringType().optional()
    }
  }, (input) => runTool(gen2(function* () {
    const refs = yield* ReferencesService;
    const saved = yield* refs.upsert(input.name, {
      domains: input.domains,
      repo: input.repo
    });
    return ok(saved);
  })));
}

// src/mcp/tools/repo-path-get.ts
function repoPathGetTool(server) {
  server.registerTool("repo_path_get", {
    description: 'Return the local path for a GitHub repo (clones if needed). Input must be "org/name".',
    inputSchema: {
      repo: stringType().describe('GitHub repo in "org/name" format')
    }
  }, (input) => runTool(gen2(function* () {
    const repos = yield* ReposService;
    const result = yield* repos.getRepoPath(input.repo);
    return ok(result);
  }).pipe(catchTag2("InvalidRepoFormat", (err) => succeed6(fail10(`Invalid repo format "${err.input}": expected "org/name"`))), catchTag2("GitCloneFailed", (err) => succeed6(fail10(`Git clone failed for "${err.repo}" (exit code ${err.exitCode})`))))));
}

// src/mcp/index.ts
var startMcpStdio = gen2(function* () {
  const server = new McpServer({
    name: "oracle",
    version
  });
  referenceGetTool(server);
  referencesSearchTool(server);
  referenceUpsertTool(server);
  referenceDeleteTool(server);
  notesReadTool(server);
  notesWriteTool(server);
  notesEditTool(server);
  repoPathGetTool(server);
  const transport = new StdioServerTransport;
  yield* promise2(() => server.connect(transport));
});

// src/cli/mcp/stdio.ts
var stdio = make26("stdio", {}, () => startMcpStdio);

// src/cli/mcp/index.ts
var mcp = make26("mcp").pipe(withSubcommands([stdio]));

// src/cli/main.ts
var oracle = make26("oracle").pipe(withSubcommands([mcp]));
var program = run5(oracle, {
  version
});
program.pipe(provide3(layer12), runtime.runPromise);
